-- Assignr — Аналітика, скаутинг та суддівство
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'assignr.com' OR LOWER(`name`) = LOWER('Assignr'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Assignr', NULL, 'https://www.assignr.com', NULL, NULL, 'Assignr — ПЗ для розкладу суддів: автоматичні призначення, комунікація й оплати для ліг, асоціацій і призначальників будь-якого розміру; мобільний застосунок, календар доступності, табличні інструменти; 14 днів безплатно.', 'Assignr is referee scheduling software: automated assignments, communication and payments for leagues, associations and assignors of any size; a mobile app, availability calendar and spreadsheet tools; 14 days free.', 'Assignr допомагає зекономити час на суддівському розкладі, автоматизуючи призначення, комунікацію та оплати. Кожен тариф включає необмежені призначення, інструменти комунікації та доступ до мобільного застосунку, а доплачувати потрібно лише за додаткові функції. Серед можливостей — табличні інструменти для ігор і суддів, гнучкий календар доступності, оцінки й рівні суддів, редагування на ходу, автоматичні push-сповіщення, збір і облік членських внесків, звіти з білінгу та виплат. Рішення підходить як для невеликих місцевих груп, так і для тих, хто координує сотні ігор на тиждень. Є 14-денний безплатний період, демо для великих організацій і порівняння з конкурентами.', 'Assignr saves time on officiating schedules by automating assignments, communication and payments. Every plan includes unlimited assignments, communication tools and mobile app access, and you only pay extra for add-on features. Capabilities include game and referee spreadsheet tools, a flexible availability calendar, referee rankings and ratings, on-the-go editing, automated push notifications, chapter dues collection and tracking, and billing and payroll reports. It suits both small local groups and those coordinating hundreds of games a week. There is a 14-day free trial, enterprise demos and competitor comparisons.', 'Автоматичні призначення суддів
Комунікація й push-сповіщення
Оплати й членські внески
Календар доступності
Мобільний застосунок
14 днів безплатно', 'Automated referee assignments
Communication and push notifications
Payments and dues
Availability calendar
Mobile app
14 days free', 'Ліги, асоціації та призначальники суддів.', 'Leagues, associations and referee assignors.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'assignr.com' OR LOWER(`name`) = LOWER('Assignr')) ORDER BY `id` LIMIT 1);
