-- Baseball Prospectus — Аналітика, скаутинг та суддівство
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'baseballprospectus.com' OR LOWER(`name`) = LOWER('Baseball Prospectus'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Baseball Prospectus', NULL, 'https://www.baseballprospectus.com', NULL, NULL, 'Baseball Prospectus — бейсбольна аналітика й скаутинг: власні метрики DRA-, DRC+ і DRP, прогнозна система PECOTA, списки перспективних гравців, драфт-борд MLB, аналіз трансферів, статистика й фентезі-інструменти.', 'Baseball Prospectus offers baseball analytics and scouting: its own DRA-, DRC+ and DRP metrics, the PECOTA projection system, prospect lists, an MLB draft board, transaction analysis, stats and fantasy tools.', 'Baseball Prospectus — видання й аналітична платформа для бейсболу. Компанія розробила власні метрики: DRA- (заслужене середнє пропущених ранів), DRC+ (заслужені створені рани) і DRP (заслужені запобіжені рани), а також прогнозну систему PECOTA, дані якої можна завантажити. Сайт містить таблиці лідерів у подачі, відбиванні, захисті й бігу, статистику PitchInfo, списки найперспективніших молодих гравців, драфт-борд MLB, аналіз трансферів, огляд вільних агентів, склади й контракти команд, список травмованих. Для фентезі-ліг є окремі інструменти. Також виходять подкасти, книжки й статті, частина яких доступна іспанською; повний доступ — за підпискою.', 'Baseball Prospectus is a publication and analytics platform for baseball. It developed its own metrics: DRA- (Deserved Run Average), DRC+ (Deserved Runs Created) and DRP (Deserved Runs Prevented), plus the PECOTA projection system, whose data can be downloaded. The site has hitting, pitching, fielding and baserunning leaderboards, PitchInfo stats, top prospect lists, an MLB draft board, transaction analysis, free agent coverage, depth charts, contracts and the injured list. Fantasy players get dedicated tools. There are also podcasts, books and articles, some in Spanish; full access requires a subscription.', 'Метрики DRA-, DRC+ і DRP
Прогнозна система PECOTA
Списки перспективних гравців
Драфт-борд MLB
Аналіз трансферів і контрактів
Подкасти й книжки', 'DRA-, DRC+ and DRP metrics
PECOTA projection system
Prospect lists
MLB draft board
Transaction and contract analysis
Podcasts and books', 'Бейсбольні аналітики, скаути, журналісти й уболівальники.', 'Baseball analysts, scouts, journalists and fans.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
