INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'Baseball Prospectus is a publication and analytics platform for baseball. It developed its own metrics: DRA- (Deserved Run Average), DRC+ (Deserved Runs Created) and DRP (Deserved Runs Prevented), plus the PECOTA projection system, whose data can be downloaded. The site has hitting, pitching, fielding and baserunning leaderboards, PitchInfo stats, top prospect lists, an MLB draft board, transaction analysis, free agent coverage, depth charts, contracts and the injured list. Fantasy players get dedicated tools. There are also podcasts, books and articles, some in Spanish; full access requires a subscription.', 'manual' FROM DUAL WHERE @new = 1;
