-- BEPRO — Аналітика, скаутинг та суддівство
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'bepro.ai' OR LOWER(`name`) = LOWER('BEPRO'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'BEPRO', NULL, 'https://bepro.ai', NULL, NULL, 'BEPRO — універсальне рішення для аналізу матчів: панорамні 4K-камери з кваліфікацією FIFA, тактичний вид і власний 3D-плеєр, ПЗ для аналізу та дані в одній платформі для запису, розбору й співпраці команд усіх рівнів.', 'BEPRO is a one-stop match analysis solution: FIFA-qualified 4K panoramic cameras, a tactical view and proprietary 3D player, analysis software and data in one platform for recording, reviewing and collaborating at every level.', 'BEPRO позбавляє команди необхідності жонглювати кількома продуктами для аналізу матчів, вирішуючи всі складнощі зйомки, аналізу та співпраці. Камери BEPRO з кваліфікацією FIFA знімають усе поле в панорамній 4K-якості, нічого не пропускаючи, і забезпечують зручний перегляд завдяки тактичному виду та власному 3D-відеоплеєру. Доступні стаціонарні та портативні рішення. Програмне забезпечення для аналізу дозволяє розмічати епізоди, готувати розбори й ділитися ними з гравцями та тренерами, а дані допомагають об''єктивно оцінювати гру. Платформа розрахована на команди всіх рівнів, має центр допомоги, демо-версію та безплатну пробу.', 'BEPRO saves teams from juggling multiple products for match analysis by solving the hassles of filming, analysis and collaboration. FIFA-qualified BEPRO cameras capture the entire pitch in 4K panoramic quality, missing nothing, and deliver an optimal viewing experience with a tactical view and a proprietary 3D video player. Fixed and portable options are available. The analysis software lets you tag clips, prepare reviews and share them with players and coaches, while data help assess play objectively. The platform is built for teams at all levels and has a help center, a demo and a free trial.', 'Панорамні 4K-камери з кваліфікацією FIFA
Тактичний вид і 3D-плеєр
ПЗ для аналізу матчів
Дані про гру
Співпраця тренерів і гравців
Безплатна проба', 'FIFA-qualified 4K panoramic cameras
Tactical view and 3D player
Match analysis software
Game data
Coach and player collaboration
Free trial', 'Футбольні та інші спортивні команди всіх рівнів, аналітики й тренери.', 'Football and other sports teams at all levels, analysts and coaches.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
