INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Beyond Sports', NULL, 'https://www.beyondsports.nl', NULL, NULL, 'Beyond Sports — компанія візуалізації спортивних даних: поєднує сирі дані трекінгу з 3D-анімацією, AI й сторітелінгом, щоб правовласники створювали занурювальні віртуальні трансляції й досвід для нового покоління фанатів.', 'Beyond Sports is a sports data visualization company: it blends raw tracking data with 3D animation, AI and storytelling so rightsholders can create immersive virtual broadcasts and experiences for the next generation of fans.', 'Beyond Sports працює на перетині спорту, технологій і занурювального сторітелінгу. Компанія допомагає власникам спортивних прав створювати інноваційні формати, які подобаються новому поколінню вболівальників. Основа — сирі дані трекінгу гравців і м''яча, які поєднуються з 3D-анімацією, AI і цікавою подачею, щоб відтворювати матчі у віртуальному середовищі. Так з''являються незвичні способи переглядати спорт, нагороджені віртуальні досвіди й нові стандарти технологічних інновацій. Рішення орієнтовані на ліги, клуби, мовників і медіа. На сайті описано рішення, реалізовані проєкти, новини та вакансії.', 'Beyond Sports operates at the intersection of sports, technology and immersive storytelling. The company helps sports rightsholders create innovative experiences that resonate with the next generation of fans. It starts from raw player and ball tracking data, combined with 3D animation, AI and captivating storytelling to recreate matches in a virtual environment. This produces new ways to consume sport, award-winning virtual experiences and new standards for tech-driven innovation. Solutions target leagues, clubs, broadcasters and media. The site covers solutions, delivered experiences, news and careers.', 'Візуалізація даних трекінгу
3D-анімація матчів
AI і сторітелінг
Віртуальні трансляції для фанатів
Рішення для правовласників', 'Tracking data visualization
3D match animation
AI and storytelling
Virtual broadcasts for fans
Solutions for rightsholders', 'Ліги, клуби, мовники й медіа зі спортивними правами.', 'Leagues, clubs, broadcasters and media with sports rights.', 'web,desktop', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
