SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'clippd.com' OR LOWER(`name`) = LOWER('Clippd'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Clippd', NULL, 'https://www.clippd.com', NULL, NULL, 'Clippd — AI-застосунок для гольфістів, що поєднує дані гри на полі й тренувань: показує, як ви граєте, що потребує уваги та як покращитися; інтеграція з технологіями на полі й поза ним, версії для тренерів і коледжів.', 'Clippd is an AI app for golfers that connects on-course play and practice data: it shows how you play, what needs attention and how to improve; integrates with on- and off-course tech, with versions for coaches and colleges.', 'Clippd — це гольф-дані для серйозних гравців. AI-застосунок з''єднує в одну картину гру на полі та тренування й дає зрозумілі рекомендації: як ви граєте, що потребує уваги й як покращитися. З кожною доданою активністю — раундами, тренуваннями, уроками й іншими сесіями — Clippd будує все детальнішу картину вашої гри. Застосунок легко інтегрується з технологіями на полі й поза ним, тож дані збираються з різних джерел. Гравці університетського рівня й тур-професіонали відзначають, що Clippd дає значно більше, ніж традиційна статистика. Є окремі рішення для гравців, тренерів і коледжів, блог і безплатний старт.', 'Clippd is golf data for serious players. The AI app connects on-course play and practice into one picture and gives clear direction: how you play, what needs attention and how to improve. With every activity you add — rounds, practice, lessons and other sessions — Clippd builds a more detailed picture of your game. It integrates easily with on- and off-course technology, so data comes from many sources. College players and tour professionals note that Clippd offers much more than traditional stats. There are dedicated solutions for players, coaches and colleges, a blog and a free start.', 'AI-аналіз гри й тренувань
Рекомендації, що покращити
Облік раундів, тренувань і уроків
Інтеграція з гольф-технологіями
Версії для тренерів і коледжів
Безплатний старт', 'AI analysis of play and practice
Direction on what to improve
Rounds, practice and lessons tracking
Golf tech integrations
Versions for coaches and colleges
Free to start', 'Серйозні гольфісти-аматори, університетські гравці й тренери.', 'Serious amateur golfers, college players and coaches.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
