SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'dataproject.com' OR LOWER(`name`) = LOWER('Data Volley'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Data Volley', NULL, 'https://www.dataproject.com', NULL, NULL, 'Data Volley від Data Project — програми для статистики й аналізу у волейболі: Data Volley 4 для професійного скаутингу, Click and Scout для планшета на лаві запасних, менеджер змагань, VolleyBoard, e-протокол і VideoCheck.', 'Data Volley by Data Project is volleyball stats and analysis software: Data Volley 4 for pro scouting, Click and Scout for a bench tablet, competition management, VolleyBoard, an e-scoresheet and VideoCheck.', 'Data Project — італійська компанія, що створює програмне забезпечення для волейболу. Для тренерів і клубів є базовий інструмент збору й аналізу Click and Scout, який дозволяє вести статистику кількома дотиками на планшеті прямо з лави запасних, і професійний Data Volley 4 для поглибленого скаутингу та статистичного аналізу; доступні версії Professional і Lite. Для федерацій і ліг компанія пропонує Web Competition Manager для керування змаганнями. Інші продукти — VolleyBoard, електронний протокол матчу e-Scoresheet, Video Sharing 4 для обміну відео та VideoCheck для перегляду спірних моментів. Є безплатна пробна версія й підтримка.', 'Data Project is an Italian company building software for volleyball. Coaches and clubs get the basic scouting tool Click and Scout, which records stats in a few taps on a tablet right from the bench, and the professional Data Volley 4 for in-depth scouting and statistical analysis, available in Professional and Lite versions. Federations and leagues can use the Web Competition Manager to run competitions. Other products include VolleyBoard, the e-Scoresheet electronic match sheet, Video Sharing 4 for exchanging video and VideoCheck for reviewing contested moments. A free trial and support are available.', 'Data Volley 4 для професійного скаутингу
Click and Scout на планшеті
Керування змаганнями
Електронний протокол матчу
VideoCheck і обмін відео
Безплатна проба', 'Data Volley 4 for pro scouting
