SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'dunksandthrees.com' OR LOWER(`name`) = LOWER('Dunks & Threes'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Dunks & Threes', NULL, 'https://dunksandthrees.com', NULL, NULL, 'Dunks & Threes — поглиблена аналітика НБА й дім показника Estimated Plus-Minus (EPM): оцінки впливу гравців, прогнози ігор і статистики на основі машинного навчання, розширена статистика та інтерактивні дашборди.', 'Dunks & Threes offers advanced NBA analytics and is home of Estimated Plus-Minus (EPM): player-impact ratings, machine-learned game and stat predictions, advanced stats and interactive dashboards.', 'Dunks & Threes — сервіс поглибленої аналітики НБА, створений Snarr Data Science. Головна розробка — Estimated Plus-Minus (EPM), ретельно оптимізований прогностичний показник впливу гравця на гру. Окрім EPM, сайт пропонує оцінки впливу гравців, прогнози результатів ігор і статистики, побудовані за допомогою машинного навчання, розширену та традиційну статистику й інтерактивні дашборди для кожної гри, гравця та команди. Є пошук гравців, інструменти для роботи зі статистикою й розділ прогнозів. Частина можливостей доступна за підпискою з кількома тарифами. Сервіс корисний аналітикам, журналістам, тренерам і вболівальникам, які хочуть глибше розуміти баскетбол.', 'Dunks & Threes is an advanced NBA analytics service built by Snarr Data Science. Its signature metric is Estimated Plus-Minus (EPM), a highly optimized predictive measure of a player''s impact. Beyond EPM, the site offers player-impact ratings, machine-learned game and stat predictions, advanced and traditional stats and interactive dashboards for every game, player and team. There is player search, stats tools and a predictions section. Some features require a subscription with several plans. It is useful for analysts, journalists, coaches and fans who want to understand basketball more deeply.', 'Показник Estimated Plus-Minus
Оцінки впливу гравців
Прогнози на основі машинного навчання
Розширена статистика
Інтерактивні дашборди', 'Estimated Plus-Minus metric
Player-impact ratings
Machine-learned predictions
Advanced stats
Interactive dashboards', 'Баскетбольні аналітики, журналісти, тренери й уболівальники НБА.', 'Basketball analysts, journalists, coaches and NBA fans.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
