SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hockeytech.com' OR LOWER(`name`) = LOWER('HockeyTech'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'HockeyTech', NULL, 'https://www.hockeytech.com', NULL, NULL, 'HockeyTech — технології, аналітика й інформаційні послуги для хокею: LeagueStat для підрахунку очок і статистики в реальному часі з інтеграцією в сайти й застосунки ліги, стрімінг HockeyTV; тепер частина FloSports.', 'HockeyTech provides hockey technology, analytics and information services: LeagueStat for real-time scoring and stats integrated with league sites and apps, and HockeyTV streaming; now part of FloSports.', 'HockeyTech надає хокейним лігам технології, аналітику та інформаційні сервіси. Система LeagueStat повністю інтегрується з адмініструванням ліги, її сайтом і мобільними застосунками та дозволяє в реальному часі вести рахунок гри, фіксуючи вилучення, кидки, голи й інші події, що автоматично оновлюють статистику. HockeyTV — канал живих трансляцій і записів матчів елітного хокею з десятками тисяч ігор на рік. Компанія також пропонує рішення для сайтів, стрімінгу й синдикації контенту. Нещодавно HockeyTech придбала компанія FloSports, щоб посилити свою хокейну пропозицію. На сайті описано продукти, історії клієнтів і кодекс етики.', 'HockeyTech provides hockey leagues with technology, analytics and information services. LeagueStat fully integrates with league administration, the website and mobile apps and enables real-time game scoring — penalties, shots, goals and other events that update stats automatically. HockeyTV is a channel for live and on-demand elite hockey streams with tens of thousands of games a year. The company also offers website, streaming and syndication solutions. HockeyTech was recently acquired by FloSports to strengthen its hockey offering. The site describes products, customer success and a code of ethics.', 'LeagueStat — рахунок і статистика наживо
