SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hoopsalytics.com' OR LOWER(`name`) = LOWER('Hoopsalytics'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Hoopsalytics', NULL, 'https://www.hoopsalytics.com', NULL, NULL, 'Hoopsalytics — баскетбольна статистика й аналітика з AI-асистентом: повністю налаштовувана статистика, бокс-скори з прив''язкою до відео, результати за 12 годин, хайлайти й підготовка до ігор; також волейбол і футбол.', 'Hoopsalytics offers basketball stats and analytics with an AI assistant: fully customizable stats, video-linked box scores, results in 12 hours, highlights and game prep; also volleyball and soccer.', 'Hoopsalytics пропонує статистику й аналітику професійного рівня для баскетбольних команд за доступною ціною. Ви завантажуєте відео гри, а через 12 годин отримуєте результати без обмежень на зберігання відео. Бокс-скори прив''язані до відео: достатньо натиснути на показник, щоб побачити відповідні епізоди. Фіксуються влучання й промахи, зони кидків, штрафні, фоли, підбирання, передачі, блоки, перехоплення, втрати, комбінації після вводу, переходи й багато іншого. AI-асистент допомагає знаходити глибокі інсайти, а хайлайти й нарізки для розборів створюються легко. Є застосунок для запису на iPad та iPhone, API, демо для професіоналів, коледжів, шкіл, ліг і AAU, а також версії для волейболу й футболу.', 'Hoopsalytics provides pro-level stats and analytics for basketball teams at an affordable price. You upload game video and get results in 12 hours with no video storage limits. Box scores are linked to video: click a stat to see the clips. It tracks makes and misses, shot locations, free throws, fouls, rebounds, assists, blocks, steals, turnovers, inbound sets, transitions and much more. An AI assistant helps uncover deep insights, and highlight reels and film sessions are easy to create. There is an iPad and iPhone recording app, an API, demos for pro, college, high school, league and AAU teams, and versions for volleyball and soccer.', 'Детальна статистика з прив''язкою до відео
Результати за 12 годин
AI-асистент для інсайтів
Хайлайти й нарізки
Застосунок для запису на iPhone/iPad
Волейбол і футбол', 'Detailed video-linked stats
Results in 12 hours
AI assistant for insights
Highlights and film sessions
iPhone/iPad recording app
Volleyball and soccer', 'Баскетбольні тренери й аналітики від шкільного до професійного рівня.', 'Basketball coaches and analysts from high school to pro level.', 'web,mobile', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
