INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Magnifi', NULL, 'https://www.magnifi.ai', NULL, NULL, 'Magnifi (тепер частина Sportz Interactive) — AI-рішення відеоінтелекту для спорту: автоматичні хайлайти, AI-тегування відео й виробництво контенту в масштабі, що прискорює створення кліпів і знижує витрати.', 'Magnifi (now part of Sportz Interactive) offers AI video intelligence for sport: automatic highlights, AI video tagging and content production at scale that speeds up clip creation and cuts costs.', 'Magnifi розвиває рішення відеоінтелекту на основі штучного інтелекту, які перетворюють відео на сильні контент-активи. Платформа автоматизує тегування відео, знаходить ключові моменти й створює хайлайти та кліпи в масштабі, заощаджуючи час і кошти. Компанія наводить, що оброблено понад 12 мільйонів годин відео, а створення контенту відбувається значно швидше, ніж вручну. Рішення допомагають спортивним організаціям, мовникам і медіа розповідати історії за допомогою AI та розширювати творчі можливості. Magnifi тепер входить до складу Sportz Interactive. На сайті описано продукти, рішення для галузей, кейси та запит на демонстрацію.', 'Magnifi develops AI-powered video intelligence that turns video into powerful content assets. The platform automates video tagging, finds key moments and creates highlights and clips at scale, saving time and money. The company reports processing over 12 million hours of video, with content created much faster than by hand. The solutions help sports organizations, broadcasters and media tell stories with AI and expand their creative potential. Magnifi is now part of Sportz Interactive. The site covers products, industry solutions, case studies and demo requests.', 'Автоматичні спортивні хайлайти
AI-тегування відео
Виробництво контенту в масштабі
Рішення для мовників і медіа
Кейси впровадження', 'Automatic sports highlights
AI video tagging
Content production at scale
Solutions for broadcasters and media
Case studies', 'Спортивні ліги, мовники, медіа й контент-команди.', 'Sports leagues, broadcasters, media and content teams.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
