SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'mevo.com' OR LOWER(`name`) = LOWER('Mevo'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Mevo', NULL, 'https://mevo.com', NULL, NULL, 'Mevo — система бездротових камер для живих трансляцій на YouTube, Facebook, Twitch та інші платформи: керування кількома камерами й перемикання ракурсів у застосунку Mevo Studio, нова 4K-камера зі змінним об''єктивом.', 'Mevo is a wireless camera system for live streaming to YouTube, Facebook, Twitch and more: direct multiple cameras and switch angles in the Mevo Studio app, plus a new 4K camera with interchangeable lenses.', 'Mevo робить багатокамерні трансляції простими й доступними: те, що раніше вимагало складного й дорогого обладнання, тепер можна зробити з кількох компактних камер і смартфона. Камери Mevo Core і Mevo Start транслюють наживо бездротово, а застосунок Mevo Studio дозволяє керувати кількома камерами й перемикати ракурси під час ефіру. Mevo Core — 4K-камера зі змінним об''єктивом. Трансляції можна вести на YouTube, Facebook, Twitch та інші платформи, а камери також працюють як вебкамери для відеоконференцій. Є застосунки Mevo Go, Camera й Webcam, аксесуари та підписка Mevo Pro з безплатним пробним періодом. Камери популярні серед шкільних і аматорських спортивних команд.', 'Mevo makes multi-camera live streaming simple and affordable: what used to require complex and expensive gear can now be done with a few compact cameras and a smartphone. Mevo Core and Mevo Start cameras stream wirelessly, and the Mevo Studio app lets you direct several cameras and switch angles during the broadcast. Mevo Core is a 4K camera with interchangeable lenses. You can stream to YouTube, Facebook, Twitch and other platforms, and the cameras also work as webcams for video conferencing. There are Mevo Go, Camera and Webcam apps, accessories and a Mevo Pro subscription with a free trial. The cameras are popular with school and amateur sports teams.', 'Бездротові камери для трансляцій
Керування кількома камерами
Застосунок Mevo Studio
4K-камера Mevo Core
Трансляції на YouTube, Facebook, Twitch
Підписка Mevo Pro', 'Wireless streaming cameras
Multi-camera control
Mevo Studio app
4K Mevo Core camera
Streaming to YouTube, Facebook, Twitch
Mevo Pro subscription', 'Шкільні й аматорські команди, клуби, організатори подій і стримери.', 'School and amateur teams, clubs, event organizers and streamers.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
