SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'once.sport' OR LOWER(`name`) = LOWER('Once Sport'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Once Sport', NULL, 'https://once.sport', NULL, NULL, 'Once Sport — зручне ПЗ для спорту: Analyser для відеоаналізу будь-якого виду, Telestrator з якісною візуалізацією, тактична дошка Coach Board і Autocam для автоматичного запису матчів; футбол, баскетбол, гандбол, хокей, регбі.', 'Once Sport offers easy sports software: Analyser for video analysis in any sport, Telestrator with great visuals, the Coach Board tactical board and Autocam automated recording; football, basketball, handball, hockey and rugby.', 'Once Sport створює просте у використанні програмне забезпечення для тренерів і аналітиків. Analyser — повноцінна програма відеоаналізу для будь-якого виду спорту: розмітка епізодів, статистика й підготовка розборів. Telestrator дозволяє малювати на відео з якісною візуалізацією тактичних рішень. Coach Board — тактична дошка, яку легко використовувати для пояснення схем і вправ. Autocam автоматично записує матчі й тренування. Рішення підходять для футболу, баскетболу, гандболу, футзалу, американського футболу, хокею, регбі та інших видів. Є порівняння продуктів, гнучкі тарифи з можливістю масштабування для команд і організацій, сертифікація, блог і безплатна пробна версія.', 'Once Sport builds easy-to-use software for coaches and analysts. Analyser is complete video analysis software for any sport: clip tagging, stats and review preparation. Telestrator lets you draw on video with superb visualizations of tactical decisions. Coach Board is a tactical board that is easy to use for explaining systems and drills. Autocam automatically records matches and training. The solutions suit football, basketball, handball, futsal, American football, hockey, rugby and more. There is a product comparison, flexible pricing that scales for teams and organizations, certification, a blog and a free trial.', 'Відеоаналіз Analyser
Телестрація Telestrator
Тактична дошка Coach Board
Автоматичний запис Autocam
Багато видів спорту
Безплатна проба', 'Analyser video analysis
Telestrator
