SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'op.gg' OR LOWER(`name`) = LOWER('OP.GG'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'OP.GG', NULL, 'https://op.gg', NULL, NULL, 'OP.GG — статистика, історія матчів, живі ігри й таблиці гравців для League of Legends у всіх режимах, а також для TFT, Valorant, PUBG, Overwatch та інших ігор; десктопний застосунок, пошук дуо й оверлей для стримерів.', 'OP.GG provides stats, match history, live games and player tables for League of Legends in every mode, plus TFT, Valorant, PUBG, Overwatch and more; a desktop app, duo finder and streamer overlay.', 'OP.GG — сервіс ігрової статистики, найбільше відомий за League of Legends. Він показує статистику, історію матчів, живі ігри й таблиці для кожного гравця в усіх режимах — Summoner''s Rift, ARAM, Arena та інших. Офіційно підтримуються також Teamfight Tactics, Palworld, Pokémon Champions, Valorant, PUBG і Overwatch, а в бета-версії — Roblox, Marvel Rivals, Arc Raiders, Counter-Strike 2, Fortnite, Diablo 4 та інші ігри. Серед нових сервісів — десктопний застосунок, пошук партнера для гри в дуо, розділ кіберспорту, оверлей для стримерів і функція Time Takers. Статистика допомагає аналізувати власну гру, обирати персонажів і готуватися до матчів.', 'OP.GG is a gaming stats service best known for League of Legends. It shows stats, match history, live games and tables for every player across all modes — Summoner''s Rift, ARAM, Arena and more. It officially supports Teamfight Tactics, Palworld, Pokémon Champions, Valorant, PUBG and Overwatch, with Roblox, Marvel Rivals, Arc Raiders, Counter-Strike 2, Fortnite, Diablo 4 and other games in beta. New services include a desktop app, a duo partner finder, an esports section, a streamer overlay and Time Takers. The stats help analyze your own play, choose champions and prepare for matches.', 'Статистика й історія матчів LoL
Живі ігри
