SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'porofessor.gg' OR LOWER(`name`) = LOWER('Porofessor'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Porofessor', NULL, 'https://porofessor.gg', NULL, NULL, 'Porofessor.gg — пошук живих ігор і статистика гравців у реальному часі для League of Legends: аналіз союзників і суперників у лобі ще до старту, ігри відомих гравців, режим стримера та внутрішньоігровий застосунок.', 'Porofessor.gg offers League of Legends live game search and real-time player statistics: analyze allies and opponents in the lobby before the game starts, featured pro games, streamer mode and an in-game app.', 'Porofessor допомагає гравцям у League of Legends підготуватися до матчу. Сервіс шукає поточну гру за ім''ям гравця й показує статистику всіх учасників у реальному часі: на яких персонажах вони грають, наскільки впевнено, які мають сильні сторони. Якщо гра ще не почалася, можна скопіювати й вставити текст обговорення з лобі в поле пошуку, щоб оцінити союзників. Доступні сервери EUW, EUNE, LAN, LAS, OCE, SEA та інші. На головній сторінці показуються ігри відомих гравців і стримерів, а режим стримера захищає від небажаної уваги. Внутрішньоігровий застосунок виводить ці дані прямо під час гри. Сервіс безплатний для основних функцій.', 'Porofessor helps League of Legends players prepare for a match. The service finds the current game by player name and shows real-time stats for every participant: which champions they play, how confidently and what their strengths are. If the game hasn''t started, you can paste the lobby chat into the search field to assess your allies. Servers include EUW, EUNE, LAN, LAS, OCE, SEA and more. The home page features games of well-known players and streamers, and streamer mode protects against unwanted attention. The in-game app shows this data right during the match. Core features are free.', 'Пошук живих ігор
Статистика гравців у реальному часі
Аналіз союзників у лобі
