SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'scope.gg' OR LOWER(`name`) = LOWER('SCOPE.GG'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SCOPE.GG', NULL, 'https://scope.gg', NULL, NULL, 'SCOPE.GG — розширена аналітика Counter-Strike 2 поза внутрішньоігровою таблицею: оцінює справжній рівень, знаходить приховані помилки, відстежує прогрес; тактична дошка, лайнапи, демо-плеєр, статистика Faceit.', 'SCOPE.GG offers advanced Counter-Strike 2 analytics beyond the in-game scoreboard: it evaluates your true skill, uncovers hidden mistakes and tracks progress; tactical board, lineups, demo viewer and Faceit stats.', 'SCOPE.GG допомагає перестати гадати й зрозуміти свої сильні та слабкі сторони в Counter-Strike 2. Сервіс рахує розширену статистику, якої немає у внутрішньоігровій таблиці, оцінює справжній рівень гри й виявляє приховані помилки, що заважають підвищувати ранг і відсоток перемог. Прогрес відстежується з часом, а розбір показує зони для росту. Особливо корисно, якщо ви часто програєте й не розумієте чому або хочете грати краще, але не знаєте, з чого почати. Серед інструментів — перевірка профілю, кліпи, лайнапи гранат, тактична дошка, порівняння гравців, статистика Faceit, передматчева аналітика, демо-плеєр, статистика прицілювання й історія матчів. Сайт доступний українською.', 'SCOPE.GG helps you stop guessing and understand your strengths and weaknesses in Counter-Strike 2. It calculates advanced stats you won''t find in the in-game scoreboard, evaluates your true skill and uncovers hidden mistakes holding back your rank and win rate. Progress is tracked over time, and reviews show growth areas. It is especially useful if you lose often without knowing why or want to play better but don''t know where to start. Tools include a profile checker, clips, grenade lineups, a tactical board, a player comparison tool, Faceit stats, pre-match analytics, a demo viewer, aim stats and match history. The site is available in Ukrainian.', 'Розширена статистика CS2
Пошук прихованих помилок
Відстеження прогресу
Тактична дошка й лайнапи
Демо-плеєр
Статистика Faceit', 'Advanced CS2 stats
Hidden mistake detection
Progress tracking
Tactical board and lineups
Demo viewer
Faceit stats', 'Гравці в Counter-Strike 2, які хочуть підвищити рівень гри.', 'Counter-Strike 2 players who want to raise their level.', 'web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
