INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Spalk', NULL, 'https://www.spalk.tv', NULL, NULL, 'Spalk — інфраструктура коментування для спортивних трансляцій: віртуальна студія коментатора, дистанційне виробництво, маркетплейс коментаторів і AI-голосовий аватар, що дозволяють транслювати спорт десятками мов.', 'Spalk is commentary infrastructure for sports broadcasts: a virtual commentary studio, remote production, a commentator marketplace and an AI voice avatar that let rightsholders broadcast sport in dozens of languages.', 'Spalk створює інфраструктуру, яка переносить коментування живого спорту по всьому світу. Віртуальна студія коментатора дозволяє коментаторам працювати дистанційно, не виїжджаючи на стадіон чи в студію мовника, а сервіси трансляцій беруть на себе технічне виробництво. Маркетплейс талантів допомагає швидко знайти коментатора потрібною мовою, а AI-голосовий аватар відкриває можливість автоматизованого коментування. Завдяки цьому правовласники можуть пропонувати трансляції багатьма мовами й з різних видів спорту та суттєво економити на виробництві. Серед партнерів — Infront, FIBA, Sky Switzerland. Коментатори можуть зареєструватися на платформі, а компанії — замовити демонстрацію.', 'Spalk builds the infrastructure that moves live sports commentary around the world. Its Virtual Commentary Studio lets commentators work remotely without traveling to the stadium or broadcaster''s studio, while broadcast services handle technical production. A talent marketplace helps find a commentator in the right language quickly, and an AI voice avatar enables automated commentary. As a result, rightsholders can offer broadcasts in many languages and sports and save significantly on production. Partners include Infront, FIBA and Sky Switzerland. Commentators can sign up on the platform, and companies can book a demo.', 'Віртуальна студія коментатора
