SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sportec-solutions.com' OR LOWER(`name`) = LOWER('Sportec Solutions'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Sportec Solutions', NULL, 'https://sportec-solutions.com', NULL, NULL, 'Sportec Solutions — спільне підприємство Deltatre і DFL Group: аналіз ігрових даних, технології для суддівства та трансляцій, нові технології й AI-рішення для стабільного розвитку футболу, народжені в серці німецького футболу.', 'Sportec Solutions is a joint venture of Deltatre and DFL Group: match data analysis, officiating and broadcast technology, new technologies and AI solutions to strengthen football, born in the heart of German football.', 'Sportec Solutions — спільне підприємство компанії Deltatre та DFL Group, що керує Бундеслігою. Компанія розвиває аналіз ігрових даних і спортивні технології, пропонуючи нові технології та рішення на основі штучного інтелекту, які допомагають сталому зміцненню гри. Портфоліо охоплює три основні напрями: збір і аналіз даних матчів, технології для суддівства й трансляцій. Компанія наголошує на безкомпромісній надійності та широкому портфелі продуктів і послуг, адаптованих до потреб користувачів, серед яких одні з найбільших ліг світу. Сайт доступний німецькою та англійською мовами, там описано продукти й вакансії.', 'Sportec Solutions is a joint venture between Deltatre and DFL Group, which runs the Bundesliga. The company advances match data analysis and sports technology, offering new technologies and AI-based solutions that help strengthen the game sustainably. Its portfolio covers three main areas: match data collection and analysis, officiating technology and broadcast solutions. The company emphasizes uncompromising reliability and a broad portfolio of products and services tailored to users, including some of the world''s largest leagues. The site is available in German and English and describes products and careers.', 'Збір і аналіз ігрових даних
