SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sportsvisio.com' OR LOWER(`name`) = LOWER('SportsVisio'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'SportsVisio', NULL, 'https://www.sportsvisio.com', NULL, NULL, 'SportsVisio — AI-статистика й хайлайти для баскетболу та волейболу: знімайте гру на будь-який пристрій і протягом 24 годин отримуйте повний бокс-скор і нарізки для кожного гравця без статистиків і ручної розмітки.', 'SportsVisio offers AI stats and highlights for basketball and volleyball: film the game on any device and within 24 hours get a full box score and clips for every player with no stat crew or manual tagging.', 'SportsVisio бере на себе всю роботу зі статистикою: ви знімаєте гру на будь-який пристрій, а протягом 24 годин отримуєте повний бокс-скор і хайлайти для кожного гравця — без команди статистиків і ручної розмітки. Тренери отримують аналітику команди та суперників у стилі НБА, ліги — конкурентну перевагу й кращий досвід для гравців, а гравці й батьки — кліпи яскравих моментів. Тариф Pro за 149 USD на місяць включає 5 ігор, повний бокс-скор, автоматичні хайлайти, повне відео гри, кліпи за статистикою й необмежених користувачів. Elite додає карти кидків, хвилини гравців, аналітику й AI-підсумок гри, а сезонний Coach — AI-асистента тренера та скаутинг суперників.', 'SportsVisio takes care of all the stats work: you film the game on any device, and within 24 hours you get a full box score and highlight clips for every player — no stat crew and no manual tagging. Coaches get NBA-style team and opponent analytics, leagues gain a competitive advantage and better player experiences, and players and parents get highlight clips. The Pro plan at 149 USD per month includes 5 games, a full box score, automatic highlight reels, full game film, clips by stat and unlimited users. Elite adds shot charts, player minutes, analytics and an AI game summary, and the seasonal Coach plan adds an AI assistant coach and opponent scouting.', 'AI-статистика з будь-якого відео
Повний бокс-скор за 24 години
Хайлайти для кожного гравця
Карти кидків і аналітика
AI-асистент тренера
Баскетбол, 3×3 і волейбол', 'AI stats from any video
Full box score within 24 hours
Highlights for every player
