SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'landing.scoutium.com' OR LOWER(`name`) = LOWER('TeamScope'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'TeamScope', NULL, 'https://landing.scoutium.com', NULL, NULL, 'TeamScope від Scoutium — доступна платформа аналітики, що знімає матчі й дає AI-інсайти елітного рівня про гравців і команду, а також чат і календар для тренерів і спортсменів; для дитячого спорту й профі.', 'TeamScope by Scoutium is an affordable analytics platform that captures match footage and delivers elite-level AI insights on players and the team, plus chat and calendar tools for coaches and athletes; for youth sports and pros.', 'TeamScope поєднує в одному застосунку все, що потрібно тренерам і гравцям, щоб не користуватися кількома окремими програмами. Платформа захоплює відео матчів і за допомогою аналітики на основі AI дає глибокі інсайти про продуктивність гравців і команди, які раніше були доступні лише професійним клубам. Водночас вона спрощує щоденну комунікацію та задачі завдяки вбудованим чату й календарю для спортсменів і тренерів. Рішення доступне за ціною та просте у використанні, тому особливо підходить для дитячого спорту, але може використовуватися й професіоналами. Є окремі розділи для клубів і тренерів, гравців і батьків, а також партнерська програма.', 'TeamScope brings everything coaches and players need into one app so they don''t have to juggle separate programs. The platform captures match footage and uses AI-powered analytics to deliver deep insights into player and team performance that used to be available only to pro clubs. It also simplifies daily communication and tasks with integrated chat and calendar tools for athletes and coaches. It is affordable and easy to use, which makes it especially suitable for youth sports, while pros can use it too. There are sections for clubs and coaches, players and parents, and a partner program.', 'Захоплення відео матчів
AI-аналітика гравців і команди
Вбудований чат
Календар команди
Для дитячого й професійного спорту', 'Match footage capture
AI player and team analytics
Built-in chat
Team calendar
For youth and pro sport', 'Дитячі та аматорські футбольні клуби, тренери, гравці й батьки.', 'Youth and amateur football clubs, coaches, players and parents.', 'mobile,web', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
