INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Tonsser', NULL, 'https://tonsser.com', NULL, NULL, 'Tonsser — футбольний застосунок для молодих гравців: профіль із хайлайтами й статистикою, відстеження виступів від матчу до матчу з оцінкою Tonsser Rating, аналіз суперників і командна стратегія перед грою.', 'Tonsser is a football app for young players: a profile with highlights and stats, match-to-match performance tracking with the Tonsser Rating, opponent analysis and team strategy before the game.', 'Tonsser — застосунок, створений для нового покоління футболістів. Гравець створює свій футбольний профіль: збирає хайлайти, відстежує статистику та формує власний образ на полі. Прогрес можна відстежувати від матчу до матчу завдяки фірмовій оцінці Tonsser Rating, яка підсумовує загальну гру. Застосунок допомагає аналізувати сильні сторони суперників, отримувати інсайти про прямого опонента й вибудовувати стратегію разом із командою перед виходом на поле. Відгуки гравців підкреслюють, що нарешті можна показати свої матчі з відео, статистикою та відзнаками кращого гравця. Застосунок доступний кількома мовами.', 'Tonsser is an app built for the next generation of football players. Players build their football profile: collect highlights, track stats and define who they are on the pitch. Progress can be tracked from match to match with the signature Tonsser Rating, which summarizes overall performance. The app helps analyze rivals'' strengths, gain insights into your direct opponent and plan strategy with your team before stepping onto the pitch. Player reviews highlight finally being able to showcase matches with videos, stats and man-of-the-match awards. The app is available in several languages.', 'Футбольний профіль гравця
Хайлайти й статистика
