-- VidSwap — Аналітика, скаутинг та суддівство
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'vidswap.com' OR LOWER(`name`) = LOWER('VidSwap'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'VidSwap', NULL, 'https://vidswap.com', NULL, NULL, 'VidSwap від Pixellot — відеоаналіз для тренерів усіх рівнів: швидкі розбори ігор, телестрація, конструктор плейбуків, теплові карти, статистика, хайлайти, необмежене сховище й обмін відео з будь-якою командою.', 'VidSwap by Pixellot offers video analysis for coaches at every level: fast game breakdowns, telestration, a playbook creator, heat maps, stats, highlights, unlimited storage and video exchange with any team.', 'VidSwap у поєднанні з AI-камерами Pixellot пропонує гнучкі й доступні інструменти відеоаналізу. Тренери отримують швидкі розбори ігор, інструменти телестрації для навчання, цифровий конструктор плейбуків, теплові карти, графіки, статистику та хайлайти. Усі пакети включають застосунки для iOS та Android, необмежене захищене сховище відео, самостійне редагування й тегування, створення хайлайтів, призначення кліпів гравцям із відстеженням перегляду та обмін відео з будь-якою командою незалежно від її відеоплатформи. VidSwap розбирає американський футбол, баскетбол, волейбол, футбол, хокей, бейсбол, софтбол, лакрос та інші види. Є окремі пакети для шкіл США та демонстрації.', 'VidSwap combined with Pixellot AI cameras delivers flexible, affordable video analysis tools. Coaches get fast game breakdowns, telestration teaching tools, a digital playbook creator, heat maps, charts, stats and highlights. All packages include iOS and Android apps, unlimited secure video storage, self-editing and tagging, highlight creation, clip assignment with review tracking and video exchange with any team regardless of their video platform. VidSwap breaks down American football, basketball, volleyball, soccer, ice hockey, baseball, softball, lacrosse and more. There are dedicated packages for US high schools and demos.', 'Розбори ігор і статистика
Телестрація й плейбуки
Теплові карти
Необмежене сховище відео
Обмін відео з будь-якою командою
Інтеграція з камерами Pixellot', 'Game breakdowns and stats
Telestration and playbooks
Heat maps
Unlimited video storage
Video exchange with any team
Pixellot camera integration', 'Шкільні, університетські та аматорські тренери й команди.', 'High school, college and amateur coaches and teams.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
