-- WSC Sports — Аналітика, скаутинг та суддівство
SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'wsc-sports.com' OR LOWER(`name`) = LOWER('WSC Sports'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'WSC Sports', NULL, 'https://wsc-sports.com', NULL, NULL, 'WSC Sports — платформа AI-контенту для спорту: автоматичне створення, керування й поширення персоналізованих хайлайтів для команд, ліг і мовників, що дозволяє за кілька хвилин створювати тисячі нарізок для цифрових платформ.', 'WSC Sports is an AI sports content platform: automatic creation, management and distribution of personalized highlights for teams, leagues and broadcasters, producing thousands of clips for digital platforms in minutes.', 'WSC Sports — піонер AI-контенту для спортивних уболівальників. Універсальна платформа автоматизує керування, створення й поширення відео: AI аналізує трансляції, знаходить ключові моменти та формує персоналізовані хайлайти й нарізки під кожну цифрову платформу. Командам, лігам і мовникам по всьому світу це дозволяє швидко випускати величезні обсяги контенту — за словами одного з клієнтів, тепер за кілька хвилин можна створити понад тисячу пакетів хайлайтів. Головні переваги — швидкість, масштаб і орієнтація на вболівальників. На сайті є опис платформи Arena, кейси клієнтів, блог і запит на демонстрацію.', 'WSC Sports pioneered AI-tailored sports content experiences for fans. Its all-in-one platform automates video management, creation and distribution: AI analyzes broadcasts, finds key moments and builds personalized highlights and clips for every digital platform. Teams, leagues and broadcasters worldwide can release huge volumes of content quickly — one client says that over 1,000 highlight packages can now be created in a few minutes. The main benefits are speed, scale and fan focus. The site covers the Arena platform, client stories, a blog and demo requests.', 'AI-хайлайти з трансляцій
Персоналізований контент для фанатів
Розповсюдження на цифрові платформи
Масштаб і швидкість
Платформа Arena', 'AI highlights from broadcasts
Personalized fan content
Distribution to digital platforms
Scale and speed
Arena platform', 'Спортивні ліги, клуби, мовники й медіа.', 'Sports leagues, clubs, broadcasters and media.', 'web', 'basic', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
